-- Super admin analytics demo bookings
-- Safe to re-run by booking_reference. The rows are intentionally confirmed
-- across several airlines, routes, and months so dashboard charts are visible.

CREATE TEMP TABLE seed_super_admin_bookings (
    booking_reference varchar(255) PRIMARY KEY,
    user_id bigint NOT NULL,
    airline_id bigint NOT NULL,
    flight_id bigint NOT NULL,
    flight_instance_id bigint NOT NULL,
    fare_id bigint NOT NULL,
    trip_type smallint NOT NULL,
    cabin_class varchar(32) NOT NULL,
    total_amount numeric(19, 2) NOT NULL,
    subtotal_amount numeric(19, 2) NOT NULL,
    discount_amount numeric(19, 2) NOT NULL,
    promo_code varchar(32),
    booking_date timestamp NOT NULL,
    contact_email varchar(255) NOT NULL,
    contact_phone varchar(64) NOT NULL
);

