INSERT INTO bookings (
    booking_reference,
    user_id,
    airline_id,
    flight_id,
    flight_instance_id,
    fare_id,
    trip_type,
    cabin_class,
    flexible_ticket,
    ticket_time_limit,
    status,
    booking_date,
    last_modified,
    ticket_issued,
    total_amount,
    subtotal_amount,
    discount_amount,
    promo_code,
    currency,
    email,
    phone
)
SELECT
    booking_reference,
    user_id,
    airline_id,
    flight_id,
    flight_instance_id,
    fare_id,
    trip_type,
    cabin_class,
    false,
    booking_date + INTERVAL '24 hours',
    'CONFIRMED',
    booking_date,
    booking_date + INTERVAL '15 minutes',
    true,
    total_amount,
    subtotal_amount,
    discount_amount,
    promo_code,
    'USD',
    contact_email,
    contact_phone
FROM seed_super_admin_bookings
ON CONFLICT (booking_reference) DO UPDATE
SET
    user_id = EXCLUDED.user_id,
    airline_id = EXCLUDED.airline_id,
    flight_id = EXCLUDED.flight_id,
    flight_instance_id = EXCLUDED.flight_instance_id,
    fare_id = EXCLUDED.fare_id,
    trip_type = EXCLUDED.trip_type,
    cabin_class = EXCLUDED.cabin_class,
    status = EXCLUDED.status,
    booking_date = EXCLUDED.booking_date,
    last_modified = EXCLUDED.last_modified,
    ticket_issued = EXCLUDED.ticket_issued,
    total_amount = EXCLUDED.total_amount,
    subtotal_amount = EXCLUDED.subtotal_amount,
    discount_amount = EXCLUDED.discount_amount,
    promo_code = EXCLUDED.promo_code,
    currency = EXCLUDED.currency,
    email = EXCLUDED.email,
    phone = EXCLUDED.phone;
